// Decide whether a watering or frost notification is needed.
// Replace USER_ID / GARDEN_ID with the demo user's ids, or map them dynamically.
const USER_ID = $env.SPROUT_DEMO_USER_ID || 'REPLACE_WITH_USER_ID';
const GARDEN_ID = $env.SPROUT_DEMO_GARDEN_ID || null;

let notification = null;

try {
  const daily = $input.first().json.daily || {};
  const minTemp = (daily.temperature_2m_min || [])[0];
  const rain = (daily.precipitation_sum || [])[0];

  if (typeof minTemp === 'number' && minTemp <= 2) {
    notification = {
      type: 'frost_warning',
      title: 'Frost expected tonight',
      message: `Low of ${minTemp}\u00b0C forecast. Cover tender crops or bring pots inside.`,
    };
  } else if (typeof rain === 'number' && rain < 1) {
    notification = {
      type: 'watering_reminder',
      title: 'Water your garden',
      message: 'Little rain expected in the next day. Give thirsty crops a deep watering.',
    };
  }
} catch (e) {
  // fall through to no-notification
}

if (!notification) return [];
return [{ json: { user_id: USER_ID, garden_id: GARDEN_ID, ...notification } }];

// Hard-coded frost warning so the demo notification always appears on cue.
const USER_ID = $env.SPROUT_DEMO_USER_ID || 'REPLACE_WITH_USER_ID';
const GARDEN_ID = $env.SPROUT_DEMO_GARDEN_ID || null;
return [{ json: {
  user_id: USER_ID,
  garden_id: GARDEN_ID,
  type: 'frost_warning',
  title: 'Frost expected tonight',
  message: 'A cold night is forecast. Cover tender crops or bring pots inside.',
} }];
